#include <iostream>
#include <algorithm>
#include <cstdint>

using namespace std;

constexpr int64_t MOD = 1000000007;

int64_t modPow(int64_t base, int64_t exp) {
    int64_t result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int64_t binomial(int64_t n, int64_t r) {
    if (r < 0 || r > n) return 0;
    r = min(r, n - r);

    int64_t numerator = 1;
    int64_t denominator = 1;

    for (int64_t i = 1; i <= r; ++i) {
        numerator = numerator * ((n - r + i) % MOD) % MOD;
        denominator = denominator * (i % MOD) % MOD;
    }

    return numerator * modPow(denominator, MOD - 2) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64_t n, m, k;
    cin >> n >> m >> k;

    if (n <= 0 || m <= 0 || k < 0 ||
        k > (n - 1) / 2 || k > (m - 1) / 2) {
        cout << 0;
        return 0;
    }

    int64_t r = 2 * k;
    cout << binomial(n - 1, r) * binomial(m - 1, r) % MOD;
    return 0;
}

