int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64_t n, m, k;
    cin >> n >> m >> k;

    constexpr int64_t MOD = 1000000007;

    if (k == 0) {
        cout << 1;
        return 0;
    }

    if (k > (n - 1) / 2 || k > (m - 1) / 2) {
        cout << 0;
        return 0;
    }

    int64_t limit = max(n, m);
    vector<int64_t> previous(limit + 1, 1);
    vector<int64_t> current(limit + 1);

    for (int64_t level = 1; level <= k; ++level) {
        fill(current.begin(), current.end(), 0);

        int64_t prefix = 0;
        int64_t value = 0;

        for (int64_t size = 3; size <= limit; ++size) {
            prefix += previous[size - 2];
            if (prefix >= MOD) prefix -= MOD;

            value += prefix;
            if (value >= MOD) value -= MOD;

            current[size] = value;
        }

        previous.swap(current);
    }

    cout << previous[n] * previous[m] % MOD;
    return 0;
}

