#include <iostream>
#include <algorithm>
#include <cstdint>

using namespace std;

using int64 = int64_t;
const int64 MOD = 1000000007;

int64 modPow(int64 base, int64 exp) {
    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int64 smallCombination(int64 n, int64 r) {
    if (r < 0 || r > n) return 0;
    r = min(r, n - r);

    int64 numerator = 1;
    int64 denominator = 1;

    for (int64 i = 1; i <= r; ++i) {
        numerator = numerator * (n - r + i) % MOD;
        denominator = denominator * i % MOD;
    }

    return numerator * modPow(denominator, MOD - 2) % MOD;
}

int64 combination(int64 n, int64 r) {
    if (r < 0 || r > n) return 0;

    int64 result = 1;
    while (n > 0 || r > 0) {
        int64 ni = n % MOD;
        int64 ri = r % MOD;
        if (ri > ni) return 0;
        result = result * smallCombination(ni, ri) % MOD;
        n /= MOD;
        r /= MOD;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m, k;
    cin >> n >> m >> k;

    if (k == 0) {
        cout << 1;
        return 0;
    }

    if (n < 3 || m < 3 || k > (n - 1) / 2 || k > (m - 1) / 2) {
        cout << 0;
        return 0;
    }

    int64 r = 2 * k;
    cout << combination(n - 1, r) * combination(m - 1, r) % MOD;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>

using namespace std;

constexpr int MOD = 1000000007;

int solveOne(int size, int k) {
    vector<int> previous(size + 1, 1);
    vector<int> current(size + 1);

    for (int step = 1; step <= k; ++step) {
        fill(current.begin(), current.end(), 0);

        int prefix = 0;
        int value = 0;

        for (int x = 3; x <= size; ++x) {
            prefix += previous[x - 2];
            if (prefix >= MOD) prefix -= MOD;

            value += prefix;
            if (value >= MOD) value -= MOD;

            current[x] = value;
        }

        previous.swap(current);
    }

    return previous[size];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    if (k > (min(n, m) - 1) / 2) {
        cout << 0;
        return 0;
    }

    cout << static_cast<int64_t>(solveOne(n, k)) * solveOne(m, k) % MOD;
    return 0;
}

